<div class="admin-page-heading"><div><h1>مرشدها</h1><p class="muted">تعیین مستقیم نقش و اطلاعات مرشد، بدون ارسال دعوت</p></div><a class="primary" href="<?= $this->h($this->url('/users/new?role=mentor')) ?>">افزودن مرشد جدید</a></div>
<section class="card section mentor-invite"><h2>تبدیل کاربر موجود به مرشد</h2><form method="get" class="search"><input type="hidden" name="r" value="/mentors"><label class="sr-only" for="candidate-q">جست‌وجوی کاربر</label><input id="candidate-q" name="candidate_q" value="<?= $this->h($candidateQuery) ?>" placeholder="نام یا شماره کاربر"><button class="secondary">پیداکردن کاربر</button></form><?= $this->start('/users/role') ?><input type="hidden" name="role" value="mentor"><label for="mentor-user">انتخاب کاربر</label><select id="mentor-user" name="id" required><option value="">کاربر را انتخاب کنید</option><?php foreach($candidates as $u): ?><option value="<?= $this->h($u['id']) ?>" <?= $selectedUser===$u['id']?'selected':'' ?>><?= $this->h(($u['display_name']?:'نام ثبت نشده').' · '.($u['phone']?:'بدون شماره')) ?></option><?php endforeach; ?></select><?= $this->field('headline','عنوان تخصص و تجربه','text','',false) ?><label for="mentor-bio">معرفی</label><textarea id="mentor-bio" name="bio" rows="3" maxlength="10000"><?= $this->val('bio') ?></textarea><?= $this->field('current_password','رمز فعلی مدیر','password') ?><button class="primary">فعال‌کردن نقش مرشد</button></form></section>
<form method="get" class="search section"><input type="hidden" name="r" value="/mentors"><label class="sr-only" for="mentor-q">جست‌وجوی مرشد</label><input id="mentor-q" name="q" value="<?= $this->h($_GET['q']??'') ?>" placeholder="جست‌وجو در مرشدها"><button class="secondary">جست‌وجو</button></form><div class="records section"><?php foreach($rows as $r): ?><article class="card mentor-admin-row"><div class="mentor-row-heading"><div><h2><?= $this->h($r['display_name']) ?></h2><p><?= $this->h($r['headline']) ?></p></div><span class="tag"><?= $r['status']==='active'?'مرشد فعال':'نقش غیرفعال' ?></span></div><a class="secondary" href="<?= $this->h($this->url('/users/edit?id='.$r['user_id'])) ?>">اطلاعات کاربر و نقش</a><details class="mentor-manage"><summary>ویرایش معرفی و نقش</summary><?= $this->start('/users/role') ?><input type="hidden" name="id" value="<?= $this->h($r['user_id']) ?>"><label>نقش<select name="role"><option value="mentor" <?= $r['status']==='active'?'selected':'' ?>>مرشد</option><option value="user" <?= $r['status']!=='active'?'selected':'' ?>>کاربر</option></select></label><?= $this->field('headline','عنوان فعالیت','text',$r['headline']) ?><label>معرفی<textarea name="bio" maxlength="10000"><?= $this->h($r['bio']) ?></textarea></label><input type="hidden" name="_atlas_present" value="1"><label class="check"><input type="checkbox" name="atlas_approved" value="1" <?= !isset($r['atlas_approved'])||$r['atlas_approved']?'checked':'' ?>>نمایش مرشد در اطلس بر اساس مکان تجربه‌های تأییدشده</label><?= $this->field('current_password','رمز فعلی مدیر','password') ?><button class="primary">ذخیره</button></form></details></article><?php endforeach; ?></div>
